{"source": "const LAT = 40; // degrees north, like Madrid, New York or Beijing
const DAYS = [21, 52, 80, 111, 141, 172, 202, 233, 264, 294, 325, 355]; // the 21st of each month
const NAMES = ["21 January", "21 February", "21 March", "21 April", "21 May", "21 June", "21 July", "21 August", "21 September", "21 October", "21 November", "21 December"];
const LETTERS = "JFMAMJJASOND";
const RAD = Math.PI / 180;
const GROUND = 300, X0 = 215, PX = 90; // ground line, left edge of the lit patch, pixels per metre

function sunAt(month, tilt) {
  const i = Math.max(0, Math.min(11, month));
  const a = Math.floor(i), b = Math.min(11, a + 1), t = i - a;
  const day = DAYS[a] + (DAYS[b] - DAYS[a]) * t;
  const dec = tilt ? 23.44 * Math.sin((2 * Math.PI * (day - 80)) / 365) : 0;
  const elev = 90 - LAT + dec;
  const cosH = Math.max(-1, Math.min(1, -Math.tan(LAT * RAD) * Math.tan(dec * RAD)));
  const H = Math.acos(cosH);                       // half the day, as an angle (radians)
  const hours = (2 * H) / RAD / 15;
  // sunlight landing on flat ground over the whole day (top of the air, relative units)
  const daily = H * Math.sin(LAT * RAD) * Math.sin(dec * RAD) + Math.cos(LAT * RAD) * Math.cos(dec * RAD) * Math.sin(H);
  return { dec, elev, hours, daily };
}
const DAILY_MAX = sunAt(5, true).daily;

figure({
  title: "Noon sunbeam",
  icon: "☀️",
  level: "5-8",
  depth: "deep",
  mode: "flat",
  size: [830, 380],
  question: "Why is summer hotter than winter?",
  caption: "Earth's tilt makes the noon sun climb high in summer and stay low in winter. A low sun spreads the same beam over more ground, so each metre gets weaker sunlight, and days are shorter too. Distance is not why: Earth is closest to the sun in January.",
  leavesOut: "This shows one place, 40° north. South of the equator the seasons are swapped. Air and clouds soak up some sunlight, and oceans store heat, so the hottest weeks come about a month after the longest day.",
  try: "Find the month when the beam spreads widest and the day is shortest.",
  tour: true,
  controls: [
    { id: "month", label: "Date", min: 0, max: 11, step: 1, value: 5, format: (v) => NAMES[Math.round(v)] },
    { id: "tilt", label: "Earth's tilt (23°)", type: "toggle", value: true },
  ],

  model(s) {
    const now = sunAt(s.month, s.tilt);
    const elevR = Math.round(now.elev);
    const spread = 1 / Math.sin(now.elev * RAD);            // metres of ground lit by a 1 m beam
    const spreadR = Math.round(spread * 100) / 100;
    const strength = Math.round(100 / spreadR);              // % of the strength of an overhead sun
    const hoursR = Math.round(now.hours);
    const dayShare = now.daily / DAILY_MAX;                  // sunlight in a whole day, vs 21 June
    return { ...now, elevR, spread, spreadR, strength, hoursR, nightR: 24 - hoursR, dayShare, dayPct: Math.round(dayShare * 100), tilt: s.tilt };
  },

  goal: (m, s) => s.tilt && Math.abs(s.month - 11) < 0.3,

  readout: (m, s) => [
    `${NAMES[Math.round(s.month)]}: the noon sun is ${m.elevR}° above the horizon.`,
    `The 1 m wide beam lands on ${m.spreadR.toFixed(2)} m of ground, so each metre gets 100 ÷ ${m.spreadR.toFixed(2)} = ${m.strength}% of the strength of a sun straight overhead.`,
    m.tilt
      ? `Daylight: ${m.hoursR} hours. Night: ${m.nightR} hours. Sunlight in the whole day: ${m.dayPct}% of 21 June's.`
      : `No tilt: every day has 12 hours of light and the same noon sun, so there are no seasons.`,
  ],

  draw(m, s, f) {
    const e = m.elev * RAD;
    const L = m.spread * PX;              // patch length in px
    const xL = X0, xR = X0 + L, cx = X0 + L / 2;
    const dx = Math.cos(e), dy = Math.sin(e);   // direction the light travels: right and down
    const nx = dy, ny = -dx;                     // across the beam
    const D = 235;                               // patch centre back to the sun
    const sx = cx - D * dx, sy = GROUND - D * dy;
    const B = D - 34;                            // the beam starts just below the sun
    const C = [cx - B * dx, GROUND - B * dy];
    const W = PX / 2;
    const beam = [
      [C[0] - W * nx, C[1] - W * ny], [C[0] + W * nx, C[1] + W * ny],
      [xR, GROUND], [xL, GROUND],
    ];
    // "1 m" marker straight across the beam
    const k = 120, mc = [cx - k * dx, GROUND - k * dy];
    const m1 = [mc[0] - W * nx, mc[1] - W * ny], m2 = [mc[0] + W * nx, mc[1] + W * ny];
    const lab = [mc[0] + 16 * dx, mc[1] + 16 * dy + 5];
    // angle label
    const [tx, ty] = f.polar(xL, GROUND, 64, 270 + m.elev / 2);

    const curve = (tilt) => (x) => sunAt(x, tilt).elev;

    const bx = 110, bw = 390, by = 350;
    const dayW = (m.hours / 24) * bw;

    return [
      f.rect(0, 0, 600, GROUND, { fill: "sky" }),
      f.text(20, 30, "Noon, 40° north", { anchor: "start", fill: "mid", size: 14 }),

      f.part("Sunbeam", f.poly(beam, { fill: "warm-soft", opacity: 0.85 }), "a beam of sunlight exactly 1 m wide. It carries the same light every day."),
      f.line(beam[0][0], beam[0][1], xL, GROUND, { stroke: "warm", width: 1.5 }),
      f.line(beam[1][0], beam[1][1], xR, GROUND, { stroke: "warm", width: 1.5 }),
      f.line(m1[0], m1[1], m2[0], m2[1], { stroke: "warm", width: 1.5, dash: "4 3" }),
      f.text(lab[0], lab[1], "1 m", { size: 14, fill: "mid" }),
      f.part("Sun", f.circle(sx, sy, 24, { fill: "sun", glow: true }), "where the sun is at noon: higher in summer, lower in winter."),

      // ground
      f.rect(0, GROUND, 600, 80, { fill: "earth" }),
      f.ground(0, 600, GROUND),
      f.part("Lit patch", f.rect(xL, GROUND - 3, L, 7, { fill: "warm", r: 3 }), "the ground the beam lands on. A longer patch means each metre gets weaker light."),
      f.arc(xL, GROUND, 40, 270, 270 + m.elev, { stroke: "accent", width: 2.5, fill: "none" }),
      f.text(tx, ty + 5, `${m.elevR}°`, { fill: "accent", weight: 600, size: 16 }),
      f.part("Ruler", f.ruler(X0, X0 + 3 * PX, GROUND + 6, { count: 6, every: 2, label: (i) => `${i / 2} m` }), "measures how many metres of ground the beam covers."),
      f.text(14, GROUND - 9, "← south", { anchor: "start", size: 14, fill: "mid" }),
      f.text(586, GROUND - 9, "north →", { anchor: "end", size: 14, fill: "mid" }),

      // sunlight in a whole day
      f.part("Day's sunlight meter", f.gauge(528, 175, 44, Math.min(1, m.dayShare), { label: "sunlight in a day" }), "all the sunlight that lands on the ground from sunrise to sunset, compared with 21 June. Strength and day length together."),

      // daylight bar
      f.part("Daylight bar", f.group([
        f.rect(bx, by, bw, 16, { fill: "night", r: 8 }),
        f.rect(bx + bw / 2 - dayW / 2, by, dayW, 16, { fill: "warm", r: 8 }),
      ]), "one whole day of 24 hours. Gold is daylight, dark is night."),
      f.text(bx - 8, by + 13, "24 h", { anchor: "end", size: 14, fill: "mid" }),
      f.text(bx + bw + 8, by + 13, `${m.hoursR} h light`, { anchor: "start", size: 14, fill: "ink" }),

      // plot of noon sun height
      f.plot(665, 50, 145, 230, {
        x: [0, 11], y: [0, 90],
        xTick: (v) => LETTERS[Math.round(v)] || "", xTicks: 12, yTicks: 4,
        xLabel: "month", yLabel: "noon sun height (°)",
        lines: s.tilt
          ? [{ fn: curve(true), stroke: "accent" }]
          : [{ fn: curve(true), stroke: "lo", dash: "4 4" }, { fn: curve(false), stroke: "accent" }],
        marks: [{ x: s.month, y: m.elev, fill: "accent", drop: true }],
      }),
    ];
  },
});
"}
